class Counter extends Map<string, number> {}
class Sub extends Counter {}
class Q<T> extends Set<T> {}
function main(): void {
  const e = new Counter();
  console.log(e);
  const s = new Sub(); s.set("k", 1);
  console.log(s, [s], { s });
  const q = new Q<number>(); q.add(7);
  console.log(q);
  console.log({ a: { b: { c: { d: s } } } });
}
